import{_ as a,o,c as e,ai as s}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"连接器与插件","description":"用连接器让 Bot 稳定地使用 Gmail、GitHub、Slack、X 等应用，以及授权时的注意事项。","frontmatter":{"related":["/basics/drafts-first","/basics/safety-approvals","/automation/routines"],"title":"连接器与插件","description":"用连接器让 Bot 稳定地使用 Gmail、GitHub、Slack、X 等应用，以及授权时的注意事项。","section":"basics","order":3,"tags":["基础","连接器","插件","MCP"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations","https://docs.x.ai/grok-bot/approvals-security-and-privacy","https://x.com/KinGao476942/status/2114228969465889003","https://x.com/grok/status/2114361747599405534"],"wordCount":836,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"连接器与插件 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"用连接器让 Bot 稳定地使用 Gmail、GitHub、Slack、X 等应用，以及授权时的注意事项。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/basics/connectors-plugins"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/basics-connectors-plugins-04c0becf43.png"}],["meta",{"property":"og:image:alt","content":"连接器与插件 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"连接器与插件 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"用连接器让 Bot 稳定地使用 Gmail、GitHub、Slack、X 等应用，以及授权时的注意事项。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/basics-connectors-plugins-04c0becf43.png"}],["meta",{"name":"twitter:image:alt","content":"连接器与插件 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/basics/connectors-plugins"}]]},"headers":[],"relativePath":"basics/connectors-plugins.md","filePath":"basics/connectors-plugins.md","lastUpdated":1792945242000}'),i={name:"basics/connectors-plugins.md"};function l(n,t,r,c,p,u){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="连接器与插件" tabindex="-1">连接器与插件 <a class="header-anchor" href="#连接器与插件" aria-label="Permalink to &quot;连接器与插件&quot;">​</a></h1><p>Bot 有两种方式使用一个外部服务：</p><ul><li><strong>通过连接器</strong>：以结构化的方式调用服务（基于 MCP 等标准），比如直接&quot;搜索邮件&quot;&quot;读取 Issue&quot;&quot;查看帖子&quot;。快、稳、不容易点错。</li><li><strong>通过浏览器</strong>：像人一样打开网页操作。适合没有连接器的网站，但网页改版、登录过期、人机验证都可能让它卡住。</li></ul><p><strong>有连接器就优先用连接器</strong>，没有再让它用浏览器。</p><h2 id="常见的连接器" tabindex="-1">常见的连接器 <a class="header-anchor" href="#常见的连接器" aria-label="Permalink to &quot;常见的连接器&quot;">​</a></h2><p>具体可用列表会持续增加，以应用内&quot;连接应用&quot;页面为准。常见的包括：</p><ul><li>邮件：Gmail、Outlook</li><li>协作：Slack、Notion</li><li>开发：GitHub</li><li>社交：X</li><li>网盘：Google Drive、OneDrive 等</li></ul><h2 id="怎么连接" tabindex="-1">怎么连接 <a class="header-anchor" href="#怎么连接" aria-label="Permalink to &quot;怎么连接&quot;">​</a></h2><ol><li>打开侧边栏的连接应用入口，或者在对话里点 Bot 弹出的连接卡片。</li><li>在浏览器里完成该服务官方的登录授权。</li><li>回到对话，告诉 Bot 可以继续。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我看看现在已经连接了哪些应用，哪些是我这个周报流程需要但还没连的。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">授权凭证不在云电脑上</p><p>通过连接器授权后，登录凭证由服务端托管，Bot 调用工具时拿不到你的令牌本身。这比在云电脑浏览器里登录更省心。</p></div><h2 id="连接器是全账号共享的" tabindex="-1">连接器是全账号共享的 <a class="header-anchor" href="#连接器是全账号共享的" aria-label="Permalink to &quot;连接器是全账号共享的&quot;">​</a></h2><p>你连接一次 Gmail，你名下所有 Bot 都能用。所以：</p><ul><li>只连接确实需要的应用。</li><li>能用只读权限或专用账号的，就别用主账号的全部权限。</li><li>定期检查已连接的应用，不用的及时移除，并到对应服务里撤销授权。</li></ul><h2 id="插件和打包技能" tabindex="-1">插件和打包技能 <a class="header-anchor" href="#插件和打包技能" aria-label="Permalink to &quot;插件和打包技能&quot;">​</a></h2><p>除了单个连接器，应用里还能安装打包好的插件或技能，一次带来一组能力和做法。安装后，在输入框里打 <code>/</code> 可以引用技能，打 <code>@</code> 可以提到 Bot、群组、例程或连接器。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Gmail 找出上周所有带附件的发票邮件，把附件下载到 /workspace/发票/ 下，按月份建文件夹。</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">写操作要设门槛</p><p>连接器既能读也可能能写：发邮件、提交代码、发帖子。建议在审批设置里给&quot;对外发送&quot;&quot;发布&quot;&quot;删除&quot;加上&quot;先问我&quot;的规则，详见<a href="/basics/safety-approvals">安全审核与授权</a>。</p></div><h2 id="飞书-lark-插件-2026-10-25-起可见" tabindex="-1">飞书 / Lark 插件（2026-10-25 起可见） <a class="header-anchor" href="#飞书-lark-插件-2026-10-25-起可见" aria-label="Permalink to &quot;飞书 / Lark 插件（2026-10-25 起可见）&quot;">​</a></h2><p>社区与 <a href="https://x.com/grok/status/2114361747599405534" target="_blank" rel="noopener noreferrer">@grok</a> 公开回复确认：在 <strong>连接应用</strong> 里可以搜索并添加飞书插件，弹窗授权后可读写信、文档，不必再为每个 Bot 单独配一套飞书 CLI 应用。</p><p>连接方式示例：对话里说「请帮我连接到飞书插件」，或打开连接应用 → 搜索「飞书」/ Feishu / Lark → 按官方弹窗授权。社区较早的说明见 <a href="https://x.com/KinGao476942/status/2114228969465889003" target="_blank" rel="noopener noreferrer">@KinGao476942</a>。</p><div class="warning custom-block"><p class="custom-block-title">账号差异与未实测声明</p><p>新插件目前更偏 <strong>Lark（国际版）</strong> 一侧；飞书账号与 Lark 账号的授权<strong>通常不通用</strong>。若授权失败，可改用飞书 CLI，或改试 Lark 国际版。<strong>本站未在本环境完成飞书 / Lark 授权</strong>，步骤来自公开说明，能力以你账号下连接应用实际列表为准。完整背景见<a href="/daily/2026-10-26-feishu-plugin">日更：飞书插件</a>。</p></div><h2 id="连不上时先查这几项" tabindex="-1">连不上时先查这几项 <a class="header-anchor" href="#连不上时先查这几项" aria-label="Permalink to &quot;连不上时先查这几项&quot;">​</a></h2><ul><li>授权是否过期：重新走一遍连接流程。</li><li>团队管理员是否禁用了该应用：界面通常会提示被管理员禁用。</li><li>服务本身是否有访问限制：比如公司邮箱只允许特定应用接入。</li></ul>',24)])])}const g=a(i,[["render",l]]);export{h as __pageData,g as default};
